from fractions import Fraction
from math import gcd, isqrt
import itertools

def _det2(m):
    return m[0] * m[3] - m[1] * m[2]

def _matmul(A, B):
    return (A[0]*B[0] + A[1]*B[2],
            A[0]*B[1] + A[1]*B[3],
            A[2]*B[0] + A[3]*B[2],
            A[2]*B[1] + A[3]*B[3])

def _inv(A):
    return (A[3], -A[1], -A[2], A[0])

def check_case(case):
    a = case['a']
    b = case['b']
    c = case['c']
    A = (case['p'], case['q'], case['r'], case['s'])
    B = (case['u'], case['v'], case['w'], case['z'])
    ok = (a * a + b * b == c * c) and (c > 0) and ((c - a) != 0)
    if ok:
        t = Fraction(b, c - a)
        x = (Fraction(1) - t * t) / (Fraction(1) + t * t)
        y = (2 * t) / (Fraction(1) + t * t)
        ok = (x == Fraction(a, c)) and (y == Fraction(b, c))
    if ok:
        ok = (_det2(A) == 1) and (_det2(B) == 1)
    if ok:
        comm = _matmul(_matmul(A, B), _matmul(_inv(A), _inv(B)))
        ok = (_det2(comm) == 1) and all(isinstance(e, int) for e in comm)
    return bool(ok == case['expect_claim'])

from fractions import Fraction
from math import gcd, isqrt
import itertools

def check_case(case):
    kind = case['kind']
    claim = False
    if kind == 'cayley':
        a = case['a']; b = case['b']; c = case['c']
        if a*a + b*b == c*c and c > 0 and a + c != 0 and gcd(gcd(a, b), c) == 1:
            t = Fraction(b, a + c)
            x = (1 - t*t) / (1 + t*t)
            y = (2*t) / (1 + t*t)
            claim = (x == Fraction(a, c)) and (y == Fraction(b, c))
    elif kind == 'pell':
        n = case['n']
        if n >= 0:
            p_km2, p_km1 = 0, 1
            q_km2, q_km1 = 1, 0
            p, q = 0, 0
            for k in range(n + 1):
                ak = 1 if k == 0 else 2
                p = ak * p_km1 + p_km2
                q = ak * q_km1 + q_km2
                p_km2, p_km1 = p_km1, p
                q_km2, q_km1 = q_km1, q
            claim = (p*p - 2*q*q == (-1)**(n + 1)) and (p - 1 <= isqrt(2*q*q) <= p)
    elif kind == 'madhava':
        m = case['m']
        if m >= 0:
            s = [Fraction(0, 1)] * (2*m + 4)
            for k in range(2*m + 3):
                s[k + 1] = s[k] + Fraction((-1)**k, 2*k + 1)
            claim = (s[2*m + 1] - s[2*m] == Fraction(1, 4*m + 1)) and (s[2*m + 2] > s[2*m]) and (s[2*m + 3] < s[2*m + 1])
    elif kind == 'commutator':
        perms = list(itertools.permutations((0, 1, 2)))
        def comp(x, y):
            return tuple(x[y[i]] for i in range(3))
        def inv(x):
            r = [0, 0, 0]
            for i in range(3):
                r[x[i]] = i
            return tuple(r)
        def sgn(x):
            s = 1
            for i in range(3):
                for j in range(i + 1, 3):
                    if x[i] > x[j]:
                        s = -s
            return s
        if case['mode'] == 'in_A3':
            claim = all(sgn(comp(comp(comp(a, b), inv(a)), inv(b))) == 1 for a in perms for b in perms)
        elif case['mode'] == 'trivial':
            claim = all(comp(comp(comp(a, b), inv(a)), inv(b)) == (0, 1, 2) for a in perms for b in perms)
    return bool(claim == case['expect_claim'])
